public class Main {
    static int[] replaceFirstCopy(int[] input, int replacement) {
        final int[] copy = input.clone();
        if (copy.length > 0) {
            copy[0] = replacement;
        }
        return copy;
    }
    public static void main(String[] args) {
        int[] values = {1, 2};
        System.out.println(replaceFirstCopy(values, 9)[0]);
    }
}

