import java.util.Scanner;
public class Harness {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt(), replacement = in.nextInt();
        int[] input = new int[n];
        for (int i = 0; i < n; i++) input[i] = in.nextInt();
        Reading reading = new Reading(input);
        boolean shared = reading.values == input;
        if (n > 0) input[0] = replacement;
        System.out.println(shared);
        System.out.println(reading.sum());
    }
}
